import{_ as o,C as a,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Sequences","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/customization/sequences.md","filePath":"master/general-settings/customization/sequences.md","lastUpdated":1792041590000}'),l={name:"master/general-settings/customization/sequences.md"};function c(u,e,m,h,d,g){const n=a("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="sequences" tabindex="-1">Sequences <a class="header-anchor" href="#sequences" aria-label="Permalink to &quot;Sequences&quot;">​</a></h1><p>A <strong>sequence</strong> is the rule that builds the number of a document, such as <code>INV/2026/00001</code>. It holds a prefix, a suffix, a counter and a padding. The app takes the next number from the sequence each time a document is created, so numbers never repeat.</p><blockquote><p><strong>In simple words:</strong> A sequence is a numbering machine. You set how the number looks, and the app counts for you.</p></blockquote><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The app creates most sequences by itself. A sequence for a journal, a warehouse or an operation type appears when you create that record. You mostly edit them here.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open <code>Settings → Sequences</code> to see all sequences.</p>',6)),s(n,{src:"/images1/general-settings/sequences_list.png",alt:"Sequences list with the New Sequence button and the Company filter"}),e[1]||(e[1]=t('<p>The list shows these columns:</p><ul><li><strong><em>Name:</em></strong> The name of the sequence.</li><li><strong><em>Code:</em></strong> The technical identifier that documents use.</li><li><strong><em>Applies To:</em></strong> The record the sequence belongs to, for example a journal. It can end with a variant: <strong>Refund</strong>, <strong>Payment</strong> or <strong>Refund + Payment</strong>.</li><li><strong><em>Company:</em></strong> The company the sequence belongs to.</li><li><strong><em>Next Document Number:</em></strong> A preview of the next number the app will give.</li><li><strong><em>Next Number:</em></strong> The counter value.</li><li><strong><em>Reset Counter:</em></strong> When the counter starts again.</li></ul><p>You can search by <strong>Name</strong> or <strong>Code</strong>, and sort most columns. Use the <strong>Company</strong> filter to see the sequences of one company. The list is sorted by <strong>Code</strong>.</p><h2 id="create-a-sequence" tabindex="-1">Create a sequence <a class="header-anchor" href="#create-a-sequence" aria-label="Permalink to &quot;Create a sequence&quot;">​</a></h2><p>Create a sequence yourself only for a custom code. Documents that need one create it for you.</p><ol><li>Go to <code>Settings → Sequences</code>.</li><li>Click <strong>New Sequence</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',6)),s(n,{src:"/images1/general-settings/sequences_create.png",alt:"New Sequence form with the General and Numbering sections"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> A name that helps you find the sequence. Optional.</li><li><strong><em>Code:</em></strong> The technical identifier used by documents, for example <code>sales.order</code>. This is required. It must be unique within the company.</li><li><strong><em>Company:</em></strong> Choose the company the sequence is for. Leave it empty to use it for all companies.</li></ul><h3 id="numbering" tabindex="-1">Numbering <a class="header-anchor" href="#numbering" aria-label="Permalink to &quot;Numbering&quot;">​</a></h3><ul><li><strong><em>Prefix:</em></strong> Text placed before the number. You can use <code>%(year)</code> (2026), <code>%(y)</code> (26), <code>%(month)</code> (10) and <code>%(day)</code> (14). For example, <code>INV/%(year)/</code>.</li><li><strong><em>Suffix:</em></strong> Text placed after the number. The same placeholders work here.</li><li><strong><em>Number Padding:</em></strong> How many digits the number has. The app adds zeros on the left. Use a value from 1 to 12. The default is 5.</li><li><strong><em>Next Number:</em></strong> The number the next document gets. The default is 1.</li><li><strong><em>Step:</em></strong> How much the counter grows each time. The default is 1.</li><li><strong><em>Reset Counter:</em></strong> When the counter goes back to 1. Choose <strong>Never</strong>, <strong>Every Year</strong> or <strong>Every Month</strong>.</li></ul>',4)),s(n,{src:"/images1/general-settings/sequences_numbering.png",alt:"Numbering section with prefix, suffix, padding, next number, step and reset counter"}),e[3]||(e[3]=t('<h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>With the prefix <code>INV/%(year)/</code>, padding 5 and next number 7, the next document number is <code>INV/2026/00007</code>.</p><h2 id="edit-a-sequence" tabindex="-1">Edit a sequence <a class="header-anchor" href="#edit-a-sequence" aria-label="Permalink to &quot;Edit a sequence&quot;">​</a></h2><ol><li>Click <strong>Edit</strong> on a row.</li><li>Change the <strong>Name</strong>, <strong>Prefix</strong>, <strong>Suffix</strong>, <strong>Number Padding</strong>, <strong>Next Number</strong>, <strong>Step</strong> or <strong>Reset Counter</strong>.</li><li>Click <strong>Save changes</strong>.</li></ol><p>You cannot change the <strong>Code</strong> or the <strong>Company</strong> of an existing sequence. A sequence made by the app also shows <strong>Applies To</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You can only raise <strong>Next Number</strong>. You cannot lower it. This stops two documents from getting the same number.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Delete does not restart at 1. The app creates the sequence again after the highest document number that exists.</p></div><p>Old documents keep their numbers when you change a sequence.</p><p>When you change <strong>Reset Counter</strong>, the app starts a new period for the counter.</p><h2 id="delete-a-sequence" tabindex="-1">Delete a sequence <a class="header-anchor" href="#delete-a-sequence" aria-label="Permalink to &quot;Delete a sequence&quot;">​</a></h2><p>Click <strong>Delete</strong> on a row, or select several rows and use the bulk delete. The app shows a confirmation message when it is done.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>New Sequence:</strong> Opens the create form.</li><li><strong>Edit:</strong> Opens the edit form of a sequence.</li><li><strong>Delete:</strong> Removes the sequence.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../companies/companies.html">Companies</a></li><li><a href="./custom-fields.html">Custom fields</a></li><li><a href="./../../finance/customer-invoices/invoice-sequence.html">Invoice sequence</a></li><li><a href="./../../finance/vendor-bills/bill-sequence.html">Bill sequence</a></li></ul>',15))])}const q=o(l,[["render",c]]);export{f as __pageData,q as default};
